html:
{% set lang = (frappe.lang or 'en').split('-')[0] %}
{% if lang not in ('fr', 'en', 'ar') %}{% set lang = 'en' %}{% endif %}
{% set labels = {'en': {'tagline': 'Together for better vision', 'title': 'Late arrival or absence report', 'date': 'Date', 'employee_section': '1. Employee information', 'employee_name': 'Name', 'designation': 'Position', 'job_description': 'Job description', 'incident_section': '2. Type of incident', 'late': 'Late for work', 'unjustified': 'Unjustified absence', 'justified': 'Justified absence', 'early': 'Early departure', 'other': 'Other', 'details_section': '3. Incident details', 'incident_date': 'Incident date', 'scheduled': 'Scheduled arrival', 'actual': 'Actual arrival', 'scheduled_departure': 'Scheduled departure', 'actual_departure': 'Actual departure', 'late_period': 'Late period', 'late_duration': 'Late duration', 'early_duration': 'Early departure duration', 'absence_duration': 'Absence duration', 'minutes': 'min', 'reason_section': '4. Reason given by the employee', 'observations_section': '5. Manager observations', 'decision_section': '6. Decision / action taken', 'verbal': 'Verbal warning', 'written': 'Written warning', 'request': 'Request for justification', 'other_action': 'Other action', 'employee_signature': 'Employee signature', 'manager_signature': 'Manager signature', 'signature_date': 'Date', 'acknowledgement': "This report is for administrative use. The employee's signature acknowledges receipt and does not necessarily indicate agreement."}, 'fr': {'tagline': 'Ensemble pour une meilleure vision', 'title': "Rapport de retard ou d'absence", 'date': 'Date', 'employee_section': '1. Informations du salarié', 'employee_name': 'Nom et prénom', 'designation': 'Poste', 'job_description': 'Fiche de poste', 'incident_section': "2. Type d'incident", 'late': 'Retard au travail', 'unjustified': 'Absence injustifiée', 'justified': 'Absence justifiée', 'early': 'Départ anticipé', 'other': 'Autre', 'details_section': "3. Détails de l'incident", 'incident_date': "Date de l'incident", 'scheduled': "Heure prévue d'arrivée", 'actual': "Heure réelle d'arrivée", 'scheduled_departure': 'Heure prévue de départ', 'actual_departure': 'Heure réelle de départ', 'late_period': 'Période de retard', 'late_duration': 'Durée du retard', 'early_duration': 'Durée du départ anticipé', 'absence_duration': "Durée de l'absence", 'minutes': 'min', 'reason_section': '4. Motif indiqué par le salarié', 'observations_section': '5. Observations du responsable', 'decision_section': '6. Décision / mesure prise', 'verbal': 'Avertissement oral', 'written': 'Avertissement écrit', 'request': 'Demande de justification', 'other_action': 'Autre mesure', 'employee_signature': 'Signature du salarié', 'manager_signature': 'Signature du responsable', 'signature_date': 'Date', 'acknowledgement': "Ce rapport est établi à des fins administratives. La signature du salarié atteste la prise de connaissance et n'implique pas nécessairement son accord."}, 'ar': {'tagline': 'معاً من أجل رؤية أفضل', 'title': 'تقرير تأخر في الوقت أو عدم الحضور', 'date': 'التاريخ', 'employee_section': '1. معلومات الموظف', 'employee_name': 'الاسم واللقب', 'designation': 'المنصب', 'job_description': 'بطاقة الوصف الوظيفي', 'incident_section': '2. نوع المخالفة', 'late': 'تأخر عن العمل', 'unjustified': 'غياب بدون مبرر', 'justified': 'غياب مبرر', 'early': 'مغادرة مبكرة', 'other': 'أخرى', 'details_section': '3. تفاصيل الحادثة', 'incident_date': 'تاريخ الحادثة', 'scheduled': 'الوقت المعتاد للحضور', 'actual': 'الوقت الفعلي للحضور', 'scheduled_departure': 'الوقت المعتاد للمغادرة', 'actual_departure': 'الوقت الفعلي للمغادرة', 'late_period': 'فترة التأخر', 'late_duration': 'مدة التأخر', 'early_duration': 'مدة المغادرة المبكرة', 'absence_duration': 'مدة الغياب', 'minutes': 'دقيقة', 'reason_section': '4. سبب التأخر أو الغياب المصرح به من طرف الموظف', 'observations_section': '5. ملاحظات المسؤول', 'decision_section': '6. القرار / الإجراء المتخذ', 'verbal': 'إنذار شفهي', 'written': 'إنذار كتابي', 'request': 'طلب تبرير', 'other_action': 'إجراء آخر', 'employee_signature': 'توقيع الموظف', 'manager_signature': 'توقيع المسؤول', 'signature_date': 'التاريخ', 'acknowledgement': 'يعد هذا التقرير لأغراض إدارية فقط، وتوقيع من طرف الموظف للإطلاع ولا يعني بالضرورة الموافقة عليه.'}} %}
{% set L = labels[lang] %}
{% set arabic = lang == 'ar' %}
{% set company_logo = frappe.db.get_value('Company', doc.company, 'company_logo') if doc.company else none %}
{% set logo_src = (frappe.utils.get_thumbnail_base64_for_image(company_logo) or {}).get('base64') if company_logo and company_logo.startswith('/files/') else none %}
{% if not logo_src %}{% set logo_src = 'data:image/jpeg;base64,' %}{% endif %}
{% set clocks = { 'scheduled_start': frappe.utils.get_datetime(doc.scheduled_start).strftime('%H:%M') if doc.scheduled_start else '', 'scheduled_end': frappe.utils.get_datetime(doc.scheduled_end).strftime('%H:%M') if doc.scheduled_end else '', 'actual_arrival': frappe.utils.get_datetime(doc.actual_arrival).strftime('%H:%M') if doc.actual_arrival else '', 'actual_departure': frappe.utils.get_datetime(doc.actual_departure).strftime('%H:%M') if doc.actual_departure else '' } %}
{% set durations = { 'late': (doc.late_minutes|string) + ' ' + L.minutes if doc.scheduled_start and doc.actual_arrival else '', 'early': (doc.early_minutes|string) + ' ' + L.minutes if doc.scheduled_end and doc.actual_departure else '', 'absence': (doc.absence_minutes|string) + ' ' + L.minutes if doc.absence_minutes else '' } %}
{% set late_period = doc.late_period or '' %}
{% set c = { 'lang': lang, 'labels': L, 'logo': logo_src, 'clocks': clocks, 'durations': durations, 'late_period': late_period } %}

<div class="incident-sheet" lang="{{ c.lang }}" dir="{{ 'rtl' if arabic else 'ltr' }}">
<style>
  @page { size: A4 portrait; margin: 8mm; }
  .incident-sheet { box-sizing: border-box; width: 100%; color: #10192e; background: #fff; font-family: "DejaVu Sans", "Noto Naskh Arabic", Arial, sans-serif; font-size: 11px; line-height: 1.35; }
  .incident-sheet * { box-sizing: border-box; }
  .incident-sheet .masthead { height: 75px; display: table; width: 100%; border-bottom: 1px solid #d9dce3; margin-bottom: 8px; }
  .incident-sheet .logo, .incident-sheet .tagline { display: table-cell; vertical-align: middle; width: 50%; }
  .incident-sheet .logo img { max-height: 85px; max-width: 170px; }
  .incident-sheet .tagline { text-align: right; font-size: 11px; font-weight: 700; }
  .incident-sheet .title { background: #081834; color: #fff; border-radius: 7px; text-align: center; font-size: 18px; font-weight: 700; padding: 7px 10px; margin: 5px 0 9px; }
  .incident-sheet .form-date { text-align: right; font-weight: 700; margin-bottom: 9px; }
  .incident-sheet .section { margin-bottom: 6px; page-break-inside: avoid; }
  .incident-sheet .section-title { font-weight: 700; font-size: 12px; text-align: left; margin: 0 2px 4px; }
  .incident-sheet .box { border: 1px solid #2a344a; border-radius: 4px; padding: 7px 10px; }
  .incident-sheet .field-row { display: table; width: 100%; min-height: 25px; margin: 1px 0; }
  .incident-sheet .field-label { display: table-cell; white-space: nowrap; font-weight: 700; width: 20%; vertical-align: bottom; padding: 3px 5px; }
  .incident-sheet .field-value { display: table-cell; width: 80%; border-bottom: 1px dotted #697185; min-height: 23px; padding: 3px 5px; vertical-align: bottom; }
  .incident-sheet .choices { display: table; width: 100%; table-layout: fixed; }
  .incident-sheet .choice { display: table-cell; font-size: 10px; white-space: nowrap; vertical-align: middle; padding: 4px 2px; }
  .incident-sheet .check { display: inline-block; border: 1px solid #24304a; border-radius: 2px; height: 14px; width: 14px; line-height: 11px; text-align: center; vertical-align: middle; font-size: 11px; margin-right: 4px; }
  .incident-sheet .other-line { margin-top: 3px; border-bottom: 1px dotted #697185; min-height: 18px; }
  .incident-sheet .details { border-collapse: collapse; width: 100%; table-layout: fixed; }
  .incident-sheet .details td { border: 1px solid #2a344a; height: 22px; padding: 2px 7px; }
  .incident-sheet .details .detail-label { width: 42%; font-weight: 700; text-align: left; }
  .incident-sheet .details .detail-value { width: 58%; text-align: center; border-bottom: 1px dotted #697185; }
  .incident-sheet .writing { min-height: 65px; white-space: pre-wrap; word-wrap: break-word; line-height: 20px; }
  .incident-sheet .writing .rule { border-bottom: 1px dotted #8890a3; height: 17px; }
  .incident-sheet .signatures { display: table; width: 100%; table-layout: fixed; border-collapse: collapse; margin-top: 8px; }
  .incident-sheet .signatures .cell { display: table-cell; border: 1px solid #2a344a; height: 62px; width: 33.333%; text-align: center; vertical-align: top; padding: 7px; }
  .incident-sheet .signature-label { font-weight: 700; }
  .incident-sheet .signature-value { margin-top: 5px; min-height: 30px; border-bottom: 1px dotted #697185; }
  .incident-sheet .signature-value img { max-height: 36px; max-width: 180px; }
  .incident-sheet .footer { margin-top: 5px; font-size: 8px; text-align: center; }
  .incident-sheet .footer-brand { font-size: 11px; font-weight: 700; margin-top: 5px; }
  .incident-sheet .ribbon { background: #081834; height: 10px; margin-top: 3px; border-radius: 2px; }
  .incident-sheet[dir="rtl"] .field-label, .incident-sheet[dir="rtl"] .details .detail-label, .incident-sheet[dir="rtl"] .section-title { text-align: right; }
  .incident-sheet[dir="rtl"] .choice .check { margin-right: 0; margin-left: 4px; }
  .incident-sheet[dir="rtl"] .details .detail-label { text-align: right; }
  .incident-sheet[dir="rtl"] .tagline, .incident-sheet[dir="rtl"] .form-date { text-align: left; }
  @media print { .incident-sheet { page-break-after: avoid; } }
</style>
  <div class="masthead">
    <div class="logo">{% if c.logo %}<img src="{{ c.logo | e }}" alt="{{ doc.company | e }}">{% else %}<strong>{{ (doc.company or "OPTILENS") | e }}</strong>{% endif %}</div>
    <div class="tagline">{{ L.tagline }}</div>
  </div>
  <div class="title">{{ L.title }}</div>
  <div class="form-date">{{ L.date }} : {{ doc.get_formatted("incident_date") }}</div>

  <div class="section">
    <div class="section-title">{{ L.employee_section }}</div>
    <div class="box">
      <div class="field-row"><span class="field-label">{{ L.employee_name }} :</span><span class="field-value">{{ (doc.employee_name or "") | e }}</span></div>
      {% if doc.designation %}<div class="field-row"><span class="field-label">{{ L.designation }} :</span><span class="field-value">{{ doc.designation | e }}</span></div>{% endif %}
      {% if doc.job_description %}<div class="field-row"><span class="field-label">{{ L.job_description }} :</span><span class="field-value">{{ doc.job_description | e }}</span></div>{% endif %}
    </div>
  </div>

  <div class="section">
    <div class="section-title">{{ L.incident_section }}</div>
    <div class="box">
      <div class="choices">
        {% for code, label in [("Late Arrival", L.late), ("Unjustified Absence", L.unjustified), ("Justified Absence", L.justified), ("Early Departure", L.early), ("Other", L.other)] %}
        <div class="choice"><span class="check">{% if doc.incident_type == code %}&#10003;{% endif %}</span>{{ label }}</div>
        {% endfor %}
      </div>
      {% if doc.incident_type == "Other" %}<div class="other-line">{{ (doc.other_incident or "") | e }}</div>{% endif %}
    </div>
  </div>

  <div class="section">
    <div class="section-title">{{ L.details_section }}</div>
    <table class="details">
      <tr><td class="detail-label">{{ L.incident_date }} :</td><td class="detail-value">{{ doc.get_formatted("incident_date") }}</td></tr>
      {% if doc.incident_type == "Late Arrival" %}
        {% if doc.scheduled_start %}
        <tr><td class="detail-label">{{ L.scheduled }} :</td><td class="detail-value">{{ c.clocks.scheduled_start }}</td></tr>
        {% endif %}
        {% if doc.actual_arrival %}
        <tr><td class="detail-label">{{ L.actual }} :</td><td class="detail-value">{{ c.clocks.actual_arrival }}</td></tr>
        {% endif %}
        {% if c.late_period %}
        <tr><td class="detail-label">{{ L.late_period }} :</td><td class="detail-value"><span dir="ltr">{{ c.late_period }}</span></td></tr>
        {% endif %}
        {% if doc.scheduled_start and doc.actual_arrival and doc.late_minutes %}
        <tr><td class="detail-label">{{ L.late_duration }} :</td><td class="detail-value">{{ c.durations.late }}</td></tr>
        {% endif %}
      {% elif doc.incident_type == "Early Departure" %}
        {% if doc.scheduled_end %}
        <tr><td class="detail-label">{{ L.scheduled_departure }} :</td><td class="detail-value">{{ c.clocks.scheduled_end }}</td></tr>
        {% endif %}
        {% if doc.actual_departure %}
        <tr><td class="detail-label">{{ L.actual_departure }} :</td><td class="detail-value">{{ c.clocks.actual_departure }}</td></tr>
        {% endif %}
        {% if doc.scheduled_end and doc.actual_departure and doc.early_minutes %}
        <tr><td class="detail-label">{{ L.early_duration }} :</td><td class="detail-value">{{ c.durations.early }}</td></tr>
        {% endif %}
      {% elif doc.incident_type in ["Justified Absence", "Unjustified Absence"] %}
        {% if doc.absence_minutes %}
        <tr><td class="detail-label">{{ L.absence_duration }} :</td><td class="detail-value">{{ c.durations.absence }}</td></tr>
        {% endif %}
      {% endif %}
    </table>
  </div>

  <div class="section">
    <div class="section-title">{{ L.reason_section }}</div>
    <div class="box writing">{{ (doc.employee_reason or "") | e }}</div>
  </div>
  <div class="section">
    <div class="section-title">{{ L.observations_section }}</div>
    <div class="box writing">{{ (doc.manager_observations or "") | e }}</div>
  </div>
  <div class="section">
    <div class="section-title">{{ L.decision_section }}</div>
    <div class="box">
      <div class="choices">
        {% for code, label in [("Verbal Warning", L.verbal), ("Written Warning", L.written), ("Request for Justification", L.request), ("Other Action", L.other_action)] %}
        <div class="choice"><span class="check">{% if doc.action_taken == code %}&#10003;{% endif %}</span>{{ label }}</div>
        {% endfor %}
      </div>
      {% if doc.action_taken == "Other Action" %}<div class="other-line">{{ (doc.other_action or "") | e }}</div>{% endif %}
    </div>
  </div>

  <div class="signatures">
    <div class="cell"><div class="signature-label">{{ L.employee_signature }}</div><div class="signature-value">{% if doc.employee_signature and doc.employee_signature.startswith("data:image/") %}<img src="{{ doc.employee_signature | e }}">{% endif %}</div></div>
    <div class="cell"><div class="signature-label">{{ L.manager_signature }}</div><div class="signature-value">{% if doc.manager_signature and doc.manager_signature.startswith("data:image/") %}<img src="{{ doc.manager_signature | e }}">{% endif %}</div></div>
    <div class="cell"><div class="signature-label">{{ L.signature_date }}</div><div class="signature-value">{{ doc.get_formatted("signature_date") if doc.signature_date else "" }}</div></div>
  </div>
  <div class="footer">{{ L.acknowledgement }}<div class="footer-brand">{{ (doc.company or "OPTILENS") | e }}</div></div>
  <div class="ribbon"></div>
</div>
